15|int
16|LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
17|{
18|    unsigned parser_flags, renderer_flags;
19|
20|    /* We interpret the 1st 8 bytes as parser flags and renderer flags. */
21|    if(size < 2 * sizeof(unsigned)) {
22|        return 0;
23|    }
24|    parser_flags = ((unsigned*)data)[0];
25|    renderer_flags = ((unsigned*)data)[1];
26|    data += 2 * sizeof(unsigned);
27|    size -= 2 * sizeof(unsigned);
28|
29|    md_html(data, size, process_output, NULL, parser_flags, renderer_flags);
30|    return 0;
