4165|md_analyze_link_contents(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines,
4166|                         int mark_beg, int mark_end)
4167|{
4168|    int i;
4169|
4170|    md_analyze_marks(ctx, lines, n_lines, mark_beg, mark_end, _T("&"), 0);
4171|    md_analyze_marks(ctx, lines, n_lines, mark_beg, mark_end, _T("*_~$"), 0);
4172|
