2994|static int
2995|md_collect_marks(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines, int table_mode)
2996|{
2997|    MD_SIZE line_index;
2998|    int ret = 0;
2999|    MD_MARK* mark;
3000|    OFF codespan_last_potential_closers[CODESPAN_MARK_MAXLEN] = { 0 };
3001|    int codespan_scanned_till_paragraph_end = FALSE;
3002|
3003|    for(line_index = 0; line_index < n_lines; line_index++) {
3004|        const MD_LINE* line = &lines[line_index];
3005|        OFF off = line->beg;
3006|
3007|        while(TRUE) {
3008|            CHAR ch;
3009|
3010|#ifdef MD4C_USE_UTF16
3011|    /* For UTF-16, mark_char_map[] covers only ASCII. */
3012|    #define IS_MARK_CHAR(off)   ((CH(off) < SIZEOF_ARRAY(ctx->mark_char_map))  &&  \
3013|                                (ctx->mark_char_map[(unsigned char) CH(off)]))
3014|#else
3015|    /* For 8-bit encodings, mark_char_map[] covers all 256 elements. */
3016|    #define IS_MARK_CHAR(off)   (ctx->mark_char_map[(unsigned char) CH(off)])
3017|#endif
3018|
3019|            /* Optimization: Use some loop unrolling. */
3020|            while(off + 3 < line->end  &&  !IS_MARK_CHAR(off+0)  &&  !IS_MARK_CHAR(off+1)
3021|                                       &&  !IS_MARK_CHAR(off+2)  &&  !IS_MARK_CHAR(off+3))
3022|                off += 4;
3023|            while(off < line->end  &&  !IS_MARK_CHAR(off+0))
3024|                off++;
3025|
3026|            if(off >= line->end)
3027|                break;
3028|
3029|            ch = CH(off);
3030|
3031|            /* A backslash escape.
3032|             * It can go beyond line->end as it may involve escaped new
3033|             * line to form a hard break. */
3034|            if(ch == _T('\\')  &&  off+1 < ctx->size  &&  (ISPUNCT(off+1) || ISNEWLINE(off+1))) {
3035|                /* Hard-break cannot be on the last line of the block. */
3036|                if(!ISNEWLINE(off+1)  ||  line_index+1 < n_lines)
3037|                    ADD_MARK(ch, off, off+2, MD_MARK_RESOLVED);
3038|                off += 2;
3039|                continue;
3040|            }
3041|
3042|            /* A potential (string) emphasis start/end. */
3043|            if(ch == _T('*')  ||  ch == _T('_')) {
3044|                OFF tmp = off+1;
3045|                int left_level;     /* What precedes: 0 = whitespace; 1 = punctuation; 2 = other char. */
3046|                int right_level;    /* What follows: 0 = whitespace; 1 = punctuation; 2 = other char. */
3047|
3048|                while(tmp < line->end  &&  CH(tmp) == ch)
3049|                    tmp++;
3050|
3051|                if(off == line->beg  ||  ISUNICODEWHITESPACEBEFORE(off))
3052|                    left_level = 0;
3053|                else if(ISUNICODEPUNCTBEFORE(off))
3054|                    left_level = 1;
3055|                else
3056|                    left_level = 2;
3057|
3058|                if(tmp == line->end  ||  ISUNICODEWHITESPACE(tmp))
3059|                    right_level = 0;
3060|                else if(ISUNICODEPUNCT(tmp))
3061|                    right_level = 1;
3062|                else
3063|                    right_level = 2;
