3065|                /* Intra-word underscore doesn't have special meaning. */
3066|                if(ch == _T('_')  &&  left_level == 2  &&  right_level == 2) {
3067|                    left_level = 0;
3068|                    right_level = 0;
3069|                }
3070|
3071|                if(left_level != 0  ||  right_level != 0) {
